input.command:
mkdir -p src/inngest src/app/api/inngest && 
cat > src/inngest/client.ts <<'EOF'
import { Inngest } from "inngest";

// Reads INNGEST_EVENT_KEY / INNGEST_SIGNING_KEY from the environment.
// In dev (`npx inngest-cli dev`) no keys are needed.
export const inngest = new Inngest({ id: "notely" });
EOF
cat > src/inngest/functions.ts <<'EOF'
import { inngest } from "./client";

export const USER_CREATED = "user/created";
export const REMINDER_DELAY = "10m";

export type UserCreatedData = { userId: string; email: string; name: string };

export const userReminder = inngest.createFunction(
  { id: "user-reminder", retries: 5, triggers: [{ event: USER_CREATED }] },
  async ({ event, step }) => {
    const { userId, email, name } = event.data as UserCreatedData;

    await step.sleep("wait-before-reminder", REMINDER_DELAY);

    // Each step is retried independently with backoff if it throws.
    await step.run("log-reminder", () => {
      console.log(`[reminder] ${name} <${email}> (user ${userId}) signed up ${REMINDER_DELAY} ago`);
    });
  },
);

export const functions = [userReminder];
EOF
cat > src/app/api/inngest/route.ts <<'EOF'
import { serve } from "inngest/next";
import { inngest } from "@/inngest/client";
import { functions } from "@/inngest/functions";

export const { GET, POST, PUT } = serve({ client: inngest, functions });
EOF
cat > .env.example <<'EOF'
# Inngest (https://app.inngest.com) — not needed for local dev with `npx inngest-cli@latest dev`
INNGEST_EVENT_KEY=placeholder-event-key
INNGEST_SIGNING_KEY=signkey-prod-placeholder
# Set to 1 locally so the SDK talks to the dev server
INNGEST_DEV=1
EOF
python3 - <<'EOF'
p='.gitignore'
s=open(p).read().replace(".env*\n",".env*\n!.env.example\n",1)
open(p,'w').write(s)
p='src/lib/users.ts'
s=open(p).read()
s=s.replace('export type User','import { inngest } from "@/inngest/client";\nimport { USER_CREATED } from "@/inngest/functions";\n\nexport type User',1)
s=s.replace('export async function getUser','''export async function createUser(input: { email: string; name: string }): Promise<User> {
  const user: User = {
    id: String(users.length + 1),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);

  // Schedules the delayed reminder job (runs 10 minutes later, with retries).
  await inngest.send({
    name: USER_CREATED,
    data: { userId: user.id, email: user.email, name: user.name },
  });

  return user;
}

export async function getUser''',1)
open(p,'w').write(s)
EOF
npx tsc --noEmit 2>&1 | head; npx eslint src 2>&1 | tail

